"use client";

import SyncTranscriptButton from "@/components/SyncTranscriptButton";
import { fetchTranscript, type TranscriptItem } from "@/lib/transcript/api";
import { useEffect, useMemo, useState } from "react";
import TranscriptExtensionConnect from "./TranscriptExtensionConnect";

type MetaState = {
  lastSyncedAt?: string | null;
  lastSyncStatus?: string | null;
  lastSyncCounts?: unknown;
} | null;

type ToastTone = "success" | "info" | "warning" | "error";

type AppToast = {
  id: string;
  tone: ToastTone;
  title: string;
  message?: string;
};

function StatCard({ label, value }: { label: string; value: string | number }) {
  return (
    <div className="app-card-strong rounded-2xl px-4 py-3">
      <div className="text-xs uppercase tracking-wide app-text-muted">
        {label}
      </div>
      <div className="mt-1 text-lg font-semibold">{value}</div>
    </div>
  );
}

function QuickStatCard({ label, value }: { label: string; value: string }) {
  return (
    <div className="app-card-strong rounded-2xl p-3">
      <div className="text-xs uppercase tracking-wide app-text-muted">
        {label}
      </div>
      <div className="mt-1 text-lg font-semibold">{value}</div>
    </div>
  );
}

function EmptyBox({
  children,
  tone = "default",
}: {
  children: React.ReactNode;
  tone?: "default" | "error";
}) {
  if (tone === "error") {
    return (
      <div className="rounded-2xl border border-red-500/30 bg-red-500/10 px-4 py-5 text-sm text-red-300">
        {children}
      </div>
    );
  }

  return (
    <div className="rounded-2xl border border-dashed border-[var(--border-main)] px-4 py-5 text-sm app-text-muted">
      {children}
    </div>
  );
}

function ToastViewport({
  toasts,
  onClose,
}: {
  toasts: AppToast[];
  onClose: (id: string) => void;
}) {
  if (!toasts.length) return null;

  function getToastStyle(tone: ToastTone): React.CSSProperties {
    if (tone === "success") {
      return {
        background: "linear-gradient(135deg, #059669, #047857)",
        color: "#ffffff",
        border: "1px solid rgba(255,255,255,0.18)",
        boxShadow: "0 18px 40px rgba(16,185,129,0.25)",
      };
    }

    if (tone === "warning") {
      return {
        background: "linear-gradient(135deg, #d97706, #b45309)",
        color: "#ffffff",
        border: "1px solid rgba(255,255,255,0.18)",
        boxShadow: "0 18px 40px rgba(245,158,11,0.24)",
      };
    }

    if (tone === "error") {
      return {
        background: "linear-gradient(135deg, #e11d48, #be123c)",
        color: "#ffffff",
        border: "1px solid rgba(255,255,255,0.18)",
        boxShadow: "0 18px 40px rgba(244,63,94,0.24)",
      };
    }

    return {
      background: "linear-gradient(135deg, #2563eb, #1d4ed8)",
      color: "#ffffff",
      border: "1px solid rgba(255,255,255,0.18)",
      boxShadow: "0 18px 40px rgba(59,130,246,0.24)",
    };
  }

  return (
    <div className="pointer-events-none fixed right-4 top-4 z-[90] flex w-[min(92vw,420px)] flex-col gap-3 md:right-6 md:top-6">
      {toasts.map((toast) => (
        <div
          key={toast.id}
          className="pointer-events-auto overflow-hidden rounded-[24px]"
          style={getToastStyle(toast.tone)}
        >
          <div className="flex items-start gap-3 px-4 py-4">
            <div
              className="mt-0.5 inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-2xl"
              style={{
                background: "rgba(255,255,255,0.14)",
                color: "#ffffff",
                border: "1px solid rgba(255,255,255,0.18)",
              }}
            >
              {toast.tone === "success"
                ? "✓"
                : toast.tone === "error"
                  ? "!"
                  : "i"}
            </div>

            <div className="min-w-0 flex-1">
              <div className="text-[15px] font-extrabold text-white">
                {toast.title}
              </div>
              {toast.message ? (
                <div className="mt-1 text-sm font-semibold leading-6 text-white">
                  {toast.message}
                </div>
              ) : null}
            </div>

            <button
              type="button"
              onClick={() => onClose(toast.id)}
              className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-full"
              style={{
                background: "rgba(255,255,255,0.14)",
                color: "#ffffff",
              }}
              aria-label="Close toast"
            >
              ×
            </button>
          </div>
        </div>
      ))}
    </div>
  );
}

function countPassed(items: TranscriptItem[]) {
  return items.filter((x) => x.status === "passed").length;
}

function countFailed(items: TranscriptItem[]) {
  return items.filter((x) => x.status === "failed").length;
}

function calcTotalCredits(items: TranscriptItem[]) {
  return items.reduce((sum, item) => sum + Number(item.credits || 0), 0);
}

function calcWeightedGpa(items: TranscriptItem[]) {
  let credits = 0;
  let weighted = 0;

  for (const item of items) {
    if (typeof item.gpa4 !== "number") continue;
    const c = Number(item.credits || 0);
    if (!Number.isFinite(c) || c <= 0) continue;

    credits += c;
    weighted += item.gpa4 * c;
  }

  if (!credits) return "--";
  return (weighted / credits).toFixed(2);
}

export default function TranscriptPage() {
  const [items, setItems] = useState<TranscriptItem[]>([]);
  const [meta, setMeta] = useState<MetaState>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [semesterFilter, setSemesterFilter] = useState("all");
  const [toasts, setToasts] = useState<AppToast[]>([]);

  function pushToast(
    tone: ToastTone,
    title: string,
    message?: string,
    duration = 3200,
  ) {
    const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    setToasts((prev) => [...prev, { id, tone, title, message }]);

    window.setTimeout(() => {
      setToasts((prev) => prev.filter((item) => item.id !== id));
    }, duration);
  }

  function removeToast(id: string) {
    setToasts((prev) => prev.filter((item) => item.id !== id));
  }

  async function load() {
    setLoading(true);
    setError(null);

    try {
      const data = await fetchTranscript(
        semesterFilter === "all" ? undefined : semesterFilter,
      );
      setItems(data.items || []);
      setMeta(data.meta ?? null);
    } catch (e) {
      setItems([]);
      setMeta(null);
      setError(String((e as Error)?.message || e));
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    void load();
  }, [semesterFilter]);

  useEffect(() => {
    const onUpdated = () => {
      pushToast(
        "success",
        "Đồng bộ bảng điểm thành công",
        "Dữ liệu bảng điểm mới nhất đã được cập nhật từ extension.",
      );
      void load();
    };

    window.addEventListener("mydtu:transcript-updated", onUpdated);
    return () => {
      window.removeEventListener("mydtu:transcript-updated", onUpdated);
    };
  }, [semesterFilter]);

  const semesters = useMemo(() => {
    return Array.from(new Set(items.map((x) => x.semester))).sort();
  }, [items]);

  const grouped = useMemo(() => {
    const map = new Map<string, TranscriptItem[]>();

    for (const item of items) {
      if (!map.has(item.semester)) map.set(item.semester, []);
      map.get(item.semester)!.push(item);
    }

    return Array.from(map.entries()).sort((a, b) => a[0].localeCompare(b[0]));
  }, [items]);

  const lastSyncedLabel = meta?.lastSyncedAt
    ? new Date(meta.lastSyncedAt).toLocaleString("vi-VN")
    : "Chưa có";

  const syncStatusTone =
    meta?.lastSyncStatus === "SUCCESS"
      ? "success"
      : meta?.lastSyncStatus === "PARTIAL"
        ? "warning"
        : meta?.lastSyncStatus === "FAILED"
          ? "error"
          : "info";

  const syncStatusLabel =
    meta?.lastSyncStatus === "SUCCESS"
      ? "Thành công"
      : meta?.lastSyncStatus === "PARTIAL"
        ? "Một phần"
        : meta?.lastSyncStatus === "FAILED"
          ? "Thất bại"
          : "Chưa có";

  const totalCredits = useMemo(() => calcTotalCredits(items), [items]);
  const passedCount = useMemo(() => countPassed(items), [items]);
  const failedCount = useMemo(() => countFailed(items), [items]);
  const overallGpa4 = useMemo(() => calcWeightedGpa(items), [items]);

  return (
    <>
      <ToastViewport toasts={toasts} onClose={removeToast} />

      <div className="mx-auto w-full max-w-7xl space-y-4">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">
              Bảng điểm tổng quan
            </h1>
            <p className="mt-1 text-sm app-text-muted">
              Đồng bộ và xem dữ liệu học tập dùng cho GPA, CPA, risk và trends.
            </p>
          </div>

          <div className="flex flex-col items-start gap-2 lg:items-end">
            <SyncTranscriptButton />
            <button
              type="button"
              onClick={() => {
                pushToast(
                  "info",
                  "Đang tải lại dữ liệu",
                  "Đang làm mới bảng điểm từ dữ liệu hiện có trong hệ thống.",
                  2200,
                );
                void load();
              }}
              className="text-sm font-medium text-[var(--accent)] hover:underline"
            >
              Tải lại dữ liệu
            </button>
          </div>
        </div>

        <div className="rounded-[28px] border border-[var(--warning)]/20 bg-[var(--warning)]/10 px-5 py-4 text-sm text-[var(--warning)] shadow-[0_10px_30px_rgba(245,158,11,0.10)]">
          <div className="font-semibold">Lưu ý đồng bộ</div>
          <div className="mt-2 leading-7 opacity-95">
            Bước 1: bấm “Mở bảng điểm MYDTU”. Bước 2: đăng nhập MYDTU nếu cần.
            Bước 3: bấm “Kiểm tra kết nối”. Bước 4: quay lại và bấm “Sync bảng
            điểm”.
          </div>
        </div>

        <TranscriptExtensionConnect />

        <div className="app-card rounded-3xl p-4">
          <div className="grid grid-cols-1 gap-3 lg:grid-cols-[260px_1fr] lg:items-end">
            <div>
              <label
                htmlFor="transcript-semester-filter"
                className="mb-2 block text-sm font-medium"
              >
                Lọc học kỳ
              </label>
              <select
                id="transcript-semester-filter"
                name="transcript-semester-filter"
                value={semesterFilter}
                onChange={(e) => setSemesterFilter(e.target.value)}
                className="app-input rounded-2xl px-3 py-2 text-sm outline-none"
                aria-label="Lọc học kỳ bảng điểm"
                title="Lọc học kỳ bảng điểm"
              >
                <option value="all">Tất cả học kỳ</option>
                {semesters.map((semester) => (
                  <option key={semester} value={semester}>
                    {semester}
                  </option>
                ))}
              </select>
            </div>

            <div className="flex flex-wrap gap-3 lg:justify-end">
              <StatCard label="Tổng môn" value={items.length} />
              <StatCard label="Số học kỳ" value={grouped.length} />
              <StatCard label="Lần sync cuối" value={lastSyncedLabel} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 gap-4 xl:grid-cols-[minmax(0,1fr)_340px]">
          <div className="space-y-4">
            <div className="app-card rounded-3xl p-4">
              {loading ? (
                <EmptyBox>Đang tải bảng điểm...</EmptyBox>
              ) : error ? (
                <EmptyBox tone="error">{error}</EmptyBox>
              ) : grouped.length === 0 ? (
                <EmptyBox>
                  Chưa có dữ liệu bảng điểm. Hãy sync từ extension trước.
                </EmptyBox>
              ) : (
                <div className="space-y-6">
                  {grouped.map(([semester, semesterItems]) => (
                    <div key={semester}>
                      <div className="mb-3 flex items-center justify-between">
                        <h3 className="text-base font-semibold">{semester}</h3>
                        <span className="app-pill rounded-full px-2.5 py-1 text-xs font-medium">
                          {semesterItems.length} môn
                        </span>
                      </div>

                      <div className="overflow-hidden rounded-3xl border border-[var(--border-main)]">
                        <div className="overflow-auto">
                          <table className="w-full min-w-[1060px] text-sm">
                            <thead className="app-text-soft bg-[var(--bg-soft)]">
                              <tr className="text-left">
                                <th className="px-4 py-3">Mã môn</th>
                                <th className="px-4 py-3">Mã lớp</th>
                                <th className="px-4 py-3">Tên môn</th>
                                <th className="px-4 py-3">Tín chỉ</th>
                                <th className="px-4 py-3">Điểm 10</th>
                                <th className="px-4 py-3">Điểm chữ</th>
                                <th className="px-4 py-3">GPA 4</th>
                                <th className="px-4 py-3">Trạng thái</th>
                              </tr>
                            </thead>
                            <tbody>
                              {semesterItems.map((item) => (
                                <tr
                                  key={item.id}
                                  className="border-t border-[var(--border-main)]"
                                >
                                  <td className="px-4 py-3 font-semibold text-[var(--accent)]">
                                    {item.courseCode}
                                  </td>
                                  <td className="px-4 py-3">
                                    {item.classCode ||
                                      item.componentsBreakdown?.classCode ||
                                      "--"}
                                  </td>
                                  <td className="px-4 py-3">
                                    {item.courseName}
                                  </td>
                                  <td className="px-4 py-3">{item.credits}</td>
                                  <td className="px-4 py-3">
                                    {item.score10 ?? "--"}
                                  </td>
                                  <td className="px-4 py-3">
                                    {item.letter ?? "--"}
                                  </td>
                                  <td className="px-4 py-3">
                                    {item.gpa4 ?? "--"}
                                  </td>
                                  <td className="px-4 py-3 capitalize">
                                    {item.status || "--"}
                                  </td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="space-y-4">
            <div className="app-card rounded-3xl p-4">
              <div className="text-sm font-semibold uppercase tracking-wide app-text-muted">
                Tổng quan nhanh
              </div>

              <div className="mt-4 rounded-3xl border border-[var(--border-main)] bg-[var(--bg-soft)]/55 p-4">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <div className="text-xs uppercase tracking-wide app-text-muted">
                      Trạng thái đồng bộ
                    </div>
                    <div className="mt-2 text-base font-semibold">
                      {syncStatusLabel}
                    </div>
                    <div className="mt-1 text-sm app-text-muted">
                      Lần sync cuối: {lastSyncedLabel}
                    </div>
                  </div>

                  <span
                    className={[
                      "inline-flex rounded-full px-3 py-1 text-xs font-semibold",
                      syncStatusTone === "success"
                        ? "app-badge-online"
                        : syncStatusTone === "warning"
                          ? "app-pill-warning"
                          : syncStatusTone === "error"
                            ? "app-pill-danger"
                            : "app-pill",
                    ].join(" ")}
                  >
                    {syncStatusLabel}
                  </span>
                </div>
              </div>

              <div className="mt-4 grid grid-cols-1 gap-3">
                <QuickStatCard label="GPA hệ 4 hiện tại" value={overallGpa4} />
                <QuickStatCard
                  label="Tổng tín chỉ"
                  value={String(totalCredits)}
                />
                <QuickStatCard label="Môn đạt" value={String(passedCount)} />
                <QuickStatCard
                  label="Môn chưa đạt"
                  value={String(failedCount)}
                />
                <QuickStatCard
                  label="Số học kỳ"
                  value={String(grouped.length)}
                />
                <QuickStatCard
                  label="Số dòng bảng điểm"
                  value={String(items.length)}
                />
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
